"""Bounds-checked binary primitives."""
import struct
from .errors import FormatError

def uint(data: bytes | bytearray, offset: int, size: int = 4, endian: str = 'little') -> int:
    if offset < 0 or size not in (1, 2, 4, 8) or offset + size > len(data):
        raise FormatError(f'truncated {size}-byte integer', offset)
    return int.from_bytes(data[offset:offset + size], endian)

def put(data: bytearray, offset: int, value: int, size: int = 4, endian: str = 'little') -> None:
    if type(value) is not int or not 0 <= value < 1 << (8 * size):
        raise ValueError(f'value must be an unsigned {8 * size}-bit integer')
    if offset < 0 or offset + size > len(data):
        raise FormatError(f'field exceeds {len(data)}-byte header', offset)
    data[offset:offset + size] = value.to_bytes(size, endian)

def prefix(data: bytes, offset: int, end: int) -> tuple[bytes, int, int]:
    if not 0 <= offset <= end <= len(data) or end - offset < 12:
        raise FormatError('truncated record prefix', offset)
    tag, header, value = struct.unpack_from('<4sII', data, offset)
    if header < 12 or header > end - offset:
        raise FormatError(f'invalid {tag!r} header length {header}', offset + 4)
    return tag, header, value

"""Lossless hdfm / partial AES-ECB / zlib container.

This layer does not assert that the decompressed bytes form a valid library.
The byte-preserving path and the forced reconstruction path are distinct.
"""
from __future__ import annotations
from dataclasses import dataclass, field
from pathlib import Path
import base64
import hashlib
import zlib
from Crypto.Cipher import AES
from .binary import uint, put
from .errors import FormatError

KEY = b'BHUILuilfghuila3'
DEFAULT_MAX_PLAIN_BYTES = 512 * 1024 * 1024

def crypt_length(body_length: int, limit: int) -> int:
    if body_length < 0 or limit < 0 or limit % 16:
        raise FormatError('AES limit must be zero or a nonnegative multiple of 16')
    return min(body_length & ~15, limit) if limit else body_length & ~15

def _header_check(header: bytes) -> None:
    if len(header) < 0x60 or header[:4] != b'hdfm':
        raise FormatError('expected hdfm header of at least 0x60 bytes', 0)
    if uint(header, 4, endian='big') != len(header):
        raise FormatError('outer header length does not match header bytes', 4)
    crypt_length(0, uint(header, 0x5c, endian='big'))

@dataclass
class Container:
    header: bytes
    payload: bytes
    trailer: bytes = b''
    _original: bytes | None = field(default=None, repr=False)
    _baseline: tuple[bytes, bytes, bytes] | None = field(default=None, repr=False)

    @classmethod
    def from_bytes(cls, data: bytes, *, max_plain_bytes: int = DEFAULT_MAX_PLAIN_BYTES,
                   strict_size: bool = True) -> Container:
        data = bytes(data)
        if type(max_plain_bytes) is not int or max_plain_bytes < 1:
            raise ValueError('max_plain_bytes must be positive')
        if len(data) < 0x60 or data[:4] != b'hdfm':
            raise FormatError('not a supported hdfm container', 0)
        hlen = uint(data, 4, endian='big')
        if hlen < 0x60 or hlen > len(data):
            raise FormatError('outer header is truncated or has invalid size', 4)
        header = data[:hlen]
        _header_check(header)
        if strict_size and uint(header, 8, endian='big') != len(data):
            raise FormatError('declared outer file size differs from actual file size', 8)
        body = data[hlen:]
        n = crypt_length(len(body), uint(header, 0x5c, endian='big'))
        decoded = AES.new(KEY, AES.MODE_ECB).decrypt(body[:n]) + body[n:]
        inflater = zlib.decompressobj()
        try:
            payload = inflater.decompress(decoded, max_plain_bytes + 1)
        except zlib.error as exc:
            raise FormatError(f'invalid encrypted/zlib payload: {exc}', hlen) from exc
        if len(payload) > max_plain_bytes or inflater.unconsumed_tail:
            raise FormatError(f'decompressed payload exceeds {max_plain_bytes} bytes', hlen)
        if not inflater.eof:
            raise FormatError('truncated zlib stream (end marker/checksum missing)', hlen)
        trailer = inflater.unused_data
        obj = cls(header, payload, trailer, data)
        obj._baseline = (header, payload, trailer)
        return obj

    @classmethod
    def read(cls, path: str | Path, **kwargs) -> Container:
        return cls.from_bytes(Path(path).read_bytes(), **kwargs)

    @property
    def version(self) -> str:
        # Pascal string, NOT a C string at 0x10.
        if len(self.header) <= 0x10:
            return ''
        n = self.header[0x10]
        if n > 15 or 0x11 + n > len(self.header):
            return ''
        return self.header[0x11:0x11 + n].decode('ascii', errors='replace')

    @property
    def max_crypt_size(self) -> int:
        return uint(self.header, 0x5c, endian='big')

    @property
    def unchanged(self) -> bool:
        return self._original is not None and self._baseline == (self.header, self.payload, self.trailer)

    def to_bytes(self, *, rebuild: bool = False, compression_level: int = 6) -> bytes:
        if type(compression_level) is not int or not -1 <= compression_level <= 9:
            raise ValueError('compression_level must be -1 through 9')
        _header_check(self.header)
        if not rebuild and self.unchanged:
            return self._original  # type: ignore[return-value]
        compressed = zlib.compress(bytes(self.payload), compression_level) + bytes(self.trailer)
        n = crypt_length(len(compressed), self.max_crypt_size)
        body = AES.new(KEY, AES.MODE_ECB).encrypt(compressed[:n]) + compressed[n:]
        header = bytearray(self.header)
        put(header, 8, len(header) + len(body), endian='big')
        return bytes(header) + body

    def write(self, path: str | Path, **kwargs) -> None:
        from .io import write_new
        write_new(Path(path), self.to_bytes(**kwargs))

    def to_dict(self) -> dict:
        return {'schema': 'itlkit.container.v1', 'header_hex': self.header.hex(),
                'payload_hex': self.payload.hex(), 'trailer_hex': self.trailer.hex(),
                'original_file_b64': base64.b64encode(self._original).decode('ascii') if self._original else None,
                'original_sha256': hashlib.sha256(self._original).hexdigest() if self._original else None}

    @classmethod
    def from_dict(cls, value: dict) -> Container:
        try:
            if value['schema'] != 'itlkit.container.v1':
                raise FormatError('unsupported container JSON schema')
            header, payload, trailer = (bytes.fromhex(value[k]) for k in ('header_hex','payload_hex','trailer_hex'))
            _header_check(header)
            original_b64 = value.get('original_file_b64')
            obj = cls.from_bytes(base64.b64decode(original_b64, validate=True)) if original_b64 else cls(header,payload,trailer)
            if original_b64 and hashlib.sha256(obj._original).hexdigest() != value.get('original_sha256'):
                raise FormatError('original container digest mismatch')
            obj.header, obj.payload, obj.trailer = header, payload, trailer
            return obj
        except (KeyError, TypeError, ValueError) as exc:
            if isinstance(exc, FormatError):
                raise
            raise FormatError(f'invalid container JSON: {exc}') from exc

"""Explicit format and unsupported-operation errors (never silent repair)."""
class ITLError(ValueError):
    """Base exception for invalid input or an unsafe/unsupported request."""

class FormatError(ITLError):
    def __init__(self, message: str, offset: int | None = None):
        self.offset = offset
        super().__init__(message + (f" at 0x{offset:x}" if offset is not None else ""))

class UnsupportedError(ITLError):
    """The byte layout can be preserved, but the requested semantics are unknown."""

"""Conservative semantic view over the reversible record tree.

Only named, understood operations are allowed. Raw bytes are exposed for research,
not as a promise that unknown fields may be edited safely.
"""
from __future__ import annotations
from pathlib import Path
import copy
from datetime import datetime, timedelta, timezone
from .binary import uint, put
from .container import Container
from .model import Node, parse_sections, serialize_sections
from .errors import FormatError, UnsupportedError

TEXT_FIELDS = {'name': 2, 'album': 3, 'artist': 4, 'genre': 5, 'kind': 6,
               'comment': 8, 'url': 11, 'composer': 12, 'path': 13,
               'album_artist': 27, 'sort_name': 30, 'sort_album': 31,
               'sort_artist': 32, 'sort_album_artist': 33, 'purchaser_name': 60}
NUMBER_FIELDS = {
    'track_id': (0x10, 4), 'record_kind_raw': (0x14, 4),
    'date_modified': (0x20, 4), 'file_size': (0x24, 4), 'total_time': (0x28, 4),
    'track_number': (0x2c, 4), 'track_count': (0x30, 4), 'year': (0x34, 4),
    'bit_rate': (0x38, 4), 'play_count': (0x4c, 4), 'play_date': (0x64, 4),
    'disc_number': (0x68, 2), 'disc_count': (0x6a, 2), 'rating': (0x6c, 1),
    'rating_aux_raw': (0x6d, 1), 'play_count_aux_raw': (0x60, 4), 'skip_count_aux_raw': (0x118, 4),
    'date_added': (0x78, 4), 'persistent_id': (0x80, 8), 'skip_count': (0xd8, 4),
    'album_id': (0xdc, 4), 'skip_date': (0x11c, 4), 'artist_id': (0x1e0, 4),
    'sample_rate': (0xf4, 4)}
READ_ONLY_FIELDS = {'track_id', 'persistent_id', 'album_id', 'artist_id', 'record_kind_raw',
                    'rating_aux_raw', 'play_count_aux_raw', 'skip_count_aux_raw', 'purchaser_name', 'kind', 'sample_rate'}
INDEXED_TEXT_FIELDS = {'album', 'artist', 'album_artist'}
ENCODINGS = {1: 'utf-16-le', 2: 'ascii', 3: 'utf-8'}
HFS_EPOCH_DELTA = 2082844800


def hfs_from_datetime(value: datetime) -> int:
    """Encode the displayed local wall time, with an explicit aware datetime."""
    if value.tzinfo is None or value.utcoffset() is None:
        raise ValueError('an aware datetime is required; timezone is never guessed')
    result = int(value.timestamp() + value.utcoffset().total_seconds() + HFS_EPOCH_DELTA)
    if not 0 <= result < 2**32:
        raise ValueError('datetime is outside the HFS uint32 range')
    return result


def hfs_to_datetime(value: int, *, utc_offset_seconds: int) -> datetime | None:
    """Decode with a caller-provided offset; zero is the unset sentinel."""
    if type(value) is not int or not 0 <= value < 2**32:
        raise ValueError('HFS timestamp must be a uint32')
    if value == 0:
        return None
    tz = timezone(timedelta(seconds=utc_offset_seconds))
    return datetime.fromtimestamp(value - HFS_EPOCH_DELTA - utc_offset_seconds, tz)


def text_nodes(parent: Node, code: int) -> list[Node]:
    return [c for c in parent.children or () if c.tag == b'mhoh' and c.type_code == code]


def read_text(node: Node) -> str:
    if node.tag != b'mhoh' or node.children is not None or len(node.payload) < 16:
        raise UnsupportedError('record does not have a known string payload')
    encoding, length = uint(node.payload, 0), uint(node.payload, 4)
    if encoding not in ENCODINGS:
        raise UnsupportedError(f'unknown string encoding {encoding}')
    if length > len(node.payload) - 16:
        raise FormatError('string length exceeds mhoh payload', node.offset)
    try:
        return node.payload[16:16 + length].decode(ENCODINGS[encoding], errors='strict')
    except UnicodeDecodeError as exc:
        raise FormatError(f'invalid {ENCODINGS[encoding]} string', node.offset) from exc


def set_text(parent: Node, code: int, value: str) -> None:
    if not isinstance(value, str) or '\x00' in value:
        raise ValueError('text must be a string without embedded NUL characters')
    nodes = text_nodes(parent, code)
    if len(nodes) > 1:
        raise UnsupportedError('ambiguous duplicate string fields')
    if parent.children is None:
        raise UnsupportedError('cannot append a string to an opaque parent')
    if nodes:
        node = nodes[0]
        if len(node.header) != 24:
            raise UnsupportedError('unverified mhoh header layout')
        read_text(node)  # refuses undecodable/unknown string representations
        old_length = uint(node.payload, 4)
        encoding = uint(node.payload, 0)
        suffix = node.payload[16 + old_length:]
        prefix_bytes = bytearray(node.payload[:16])
    else:
        h = bytearray(24)
        h[:4] = b'mhoh'; put(h, 4, 24); put(h, 8, 40); put(h, 12, code)
        node = Node(h)
        old_length, suffix, prefix_bytes, encoding = 0, b'', bytearray(16), 3
    if code == 11:
        encoding = 2  # URL must be percent-encoded ASCII, never lossy replacement.
    elif any(ord(ch) > 127 for ch in value):
        encoding = 1
    try:
        data = value.encode(ENCODINGS[encoding], errors='strict')
    except UnicodeEncodeError as exc:
        raise ValueError('URL must be ASCII/percent-encoded') from exc
    if suffix and len(data) != old_length:
        raise UnsupportedError('cannot resize a string with an unknown trailing suffix')
    put(prefix_bytes, 0, encoding); put(prefix_bytes, 4, len(data))
    node.payload = bytes(prefix_bytes) + data + suffix
    if not nodes:
        # Keep all mhoh metadata before item records.
        index = next((i for i, c in enumerate(parent.children) if c.tag != b'mhoh'), len(parent.children))
        parent.children.insert(index, node)


def _parse_pid(value) -> int:
    if isinstance(value, str):
        text = value[2:] if value.startswith(('0x', '0X')) else value
        if len(text) != 16 or any(c not in '0123456789abcdefABCDEF' for c in text):
            raise ValueError('persistent ID must contain exactly 16 hexadecimal digits')
        value = int(text, 16)
    if type(value) is not int or not 0 < value < 2**64:
        raise ValueError('persistent ID must be a nonzero uint64')
    return value


class Track:
    def __init__(self, library: Library, node: Node):
        self.library, self.node = library, node

    @property
    def track_id(self) -> int:
        return uint(self.node.header, 0x10)

    @property
    def persistent_id(self) -> int:
        return uint(self.node.header, 0x80, 8)

    def get(self, field: str):
        if field in NUMBER_FIELDS:
            return uint(self.node.header, *NUMBER_FIELDS[field])
        if field == 'loved':
            return bool(uint(self.node.header, 0x2bc) & 0x02000000)
        if field == 'compilation':
            return bool(uint(self.node.header, 0x50) & 0x01000000)
        if field in TEXT_FIELDS:
            nodes = text_nodes(self.node, TEXT_FIELDS[field])
            if len(nodes) > 1:
                raise UnsupportedError(f'duplicate text field {field}')
            return read_text(nodes[0]) if nodes else None
        raise UnsupportedError(f'unknown track field: {field}')

    def set(self, **fields) -> None:
        if not any(n is self.node for n in self.library._records(1, b'mith')):
            raise ValueError('stale track handle; reselect by persistent ID after a library transaction')
        self.library._require_semantic_profile()
        for name in ('url', 'path'):
            if name in fields and fields[name] != self.get(name) and any(
                    c.tag == b'mhoh' and c.type_code == 1 for c in self.node.children or ()):
                raise UnsupportedError('relocation requires updating the opaque file-location object; refusing a URL/path-only change')
        if any(name in INDEXED_TEXT_FIELDS for name in fields):
            from .trackops import set_indexed_fields
            updated = set_indexed_fields(self.library, self.persistent_id, fields)
            self.node = updated.node
            return
        if len(self.node.header) != 756:
            raise UnsupportedError('track writes require the observed 756-byte mith profile')
        candidate = copy.deepcopy(self.node)
        for field, value in fields.items():
            if field in READ_ONLY_FIELDS:
                raise UnsupportedError(f'{field} is read-only (identity/derived/provenance field)')
            if field in INDEXED_TEXT_FIELDS:
                raise UnsupportedError(f'{field} changes require unresolved album/artist index maintenance')
            if field in TEXT_FIELDS:
                set_text(candidate, TEXT_FIELDS[field], value)
            elif field == 'loved':
                if type(value) is not bool:
                    raise ValueError('loved must be true or false')
                flags = uint(candidate.header, 0x2bc)
                put(candidate.header, 0x2bc, flags | 0x02000000 if value else flags & ~0x02000000)
            elif field in NUMBER_FIELDS:
                if field == 'rating' and (type(value) is not int or not 0 <= value <= 100):
                    raise ValueError('rating must be an integer from 0 to 100')
                off, size = NUMBER_FIELDS[field]
                put(candidate.header, off, value, size)
                # Native COM writes prove +0x60/+0x118 are NOT unconditional mirrors.
                # Preserve those unknown counters rather than corrupt their independent state.
            else:
                raise UnsupportedError(f'unknown track field: {field}')
        self.node.header, self.node.children, self.node.payload = candidate.header, candidate.children, candidate.payload

    def to_dict(self) -> dict:
        result = {}
        for field in [*NUMBER_FIELDS, *TEXT_FIELDS, 'loved', 'compilation']:
            try:
                value = self.get(field)
            except (FormatError, UnsupportedError) as exc:
                result.setdefault('field_errors', {})[field] = str(exc)
                continue
            result[field] = f'{value:016X}' if field == 'persistent_id' else value
        return result


class Playlist:
    def __init__(self, library: Library, node: Node):
        self.library, self.node = library, node

    @property
    def persistent_id(self) -> int:
        return uint(self.node.header, 0x1b8, 8)

    @property
    def playlist_id(self) -> int:
        return uint(self.node.header, 0xd40)

    @property
    def name(self) -> str | None:
        nodes = text_nodes(self.node, 100)
        if len(nodes) > 1:
            raise UnsupportedError('duplicate playlist title')
        return read_text(nodes[0]) if nodes else None

    @property
    def items(self) -> list[Node]:
        return [c for c in self.node.children or () if c.tag == b'mtph']

    @property
    def track_ids(self) -> list[int]:
        return [uint(c.header, 0x18) for c in self.items]

    @property
    def is_master(self) -> bool:
        return bool(uint(self.node.header, 0x14) & 0x10000)

    @property
    def is_smart(self) -> bool:
        return any(c.type_code in (101, 102) for c in self.node.children or () if c.tag == b'mhoh')

    @property
    def is_plain(self) -> bool:
        return (len(self.node.header) == 3500 and not self.is_master and not self.is_smart
                and uint(self.node.header, 0x238) == 0
                and not any(c.type_code == 103 for c in self.node.children or () if c.tag == b'mhoh'))

    def rename(self, name: str) -> None:
        if not any(n is self.node for n in self.library._records(2, b'miph')):
            raise ValueError('stale playlist handle; reselect after a library transaction')
        self.library._require_semantic_profile()
        if not self.is_plain:
            raise UnsupportedError('only ordinary, non-system, non-smart playlists may be renamed')
        candidate = copy.deepcopy(self.node)
        set_text(candidate, 100, name)
        self.node.header, self.node.children = candidate.header, candidate.children

    def replace_members(self, track_persistent_ids) -> None:
        from .operations import replace_playlist_members
        current = replace_playlist_members(self.library, self.persistent_id, track_persistent_ids)
        self.node = current.node

    def to_dict(self) -> dict:
        result = {'name': self.name, 'track_ids': self.track_ids}
        for name in ('persistent_id', 'playlist_id', 'is_master', 'is_smart', 'is_plain'):
            try:
                value = getattr(self, name)
                result[name] = f'{value:016X}' if name == 'persistent_id' else value
            except FormatError as exc:
                result.setdefault('field_errors', {})[name] = str(exc)
        result['item_persistent_ids'] = [f'{uint(n.header, 0x44, 8):016X}' if len(n.header) >= 0x4c else None for n in self.items]
        return result


class Library:
    def __init__(self, container: Container):
        self.container = container
        self.sections = parse_sections(container.payload)
        self._validate()

    @classmethod
    def from_bytes(cls, data: bytes, **kwargs) -> Library:
        return cls(Container.from_bytes(data, **kwargs))

    @classmethod
    def read(cls, path: str | Path, **kwargs) -> Library:
        return cls.from_bytes(Path(path).read_bytes(), **kwargs)

    def _root(self, section_type: int) -> Node | None:
        nodes = [s for s in self.sections if s.section_type == section_type]
        if len(nodes) > 1:
            raise FormatError(f'duplicate section type {section_type}')
        if not nodes:
            return None
        return nodes[0].children[0] if nodes[0].children else None

    def _records(self, section_type: int, tag: bytes) -> list[Node]:
        root = self._root(section_type)
        return [c for c in root.children or () if c.tag == tag] if root else []

    @property
    def tracks(self) -> list[Track]:
        return [Track(self, n) for n in self._records(1, b'mith')]

    @property
    def playlists(self) -> list[Playlist]:
        return [Playlist(self, n) for n in self._records(2, b'miph')]

    @property
    def persistent_id(self) -> int:
        return uint(self.container.header, 0x34, 8, endian='big')

    def track(self, *, track_id: int | None = None, persistent_id: int | str | None = None) -> Track:
        if (track_id is None) == (persistent_id is None):
            raise ValueError('supply exactly one track_id or persistent_id')
        if track_id is not None and (type(track_id) is not int or not 0 < track_id < 2**32):
            raise ValueError('track_id must be a nonzero uint32')
        if persistent_id is not None:
            persistent_id = _parse_pid(persistent_id)
        matches = [t for t in self.tracks if (t.track_id == track_id if track_id is not None else t.persistent_id == persistent_id)]
        if len(matches) != 1:
            raise ValueError(f'track selector matched {len(matches)} records')
        return matches[0]

    def playlist(self, persistent_id: int | str) -> Playlist:
        persistent_id = _parse_pid(persistent_id)
        matches = [p for p in self.playlists if p.persistent_id == persistent_id]
        if len(matches) != 1:
            raise ValueError(f'playlist selector matched {len(matches)} records')
        return matches[0]

    def add_track_from(self, source: Library, persistent_id) -> Track:
        from .trackops import add_track_from
        return add_track_from(self, source, persistent_id)

    def delete_track(self, persistent_id) -> None:
        from .trackops import delete_track
        delete_track(self, persistent_id)

    def create_playlist(self, name: str, **kwargs) -> Playlist:
        from .operations import create_playlist
        return create_playlist(self, name, **kwargs)

    def delete_playlist(self, persistent_id) -> None:
        from .operations import delete_playlist
        delete_playlist(self, persistent_id)

    def replace_playlist_members(self, persistent_id, track_persistent_ids) -> Playlist:
        from .operations import replace_playlist_members
        return replace_playlist_members(self, persistent_id, track_persistent_ids)

    def _counts(self) -> dict[int, int]:
        return {0x44: len(self.tracks), 0x48: len(self.playlists),
                0x4c: len(self._records(9, b'miah')), 0x54: len(self._records(11, b'miih'))}

    def _validate(self) -> None:
        mfdh = self._root(16)
        if not mfdh:
            raise FormatError('missing main mfdh section')
        if uint(mfdh.header, 8) != len(self.container.payload) + len(self.container.header):
            raise FormatError('mfdh logical size differs from payload + outer header', mfdh.offset)
        if uint(mfdh.header, 0x30) != len(self.sections):
            raise FormatError('mfdh section count mismatch', mfdh.offset)
        for offset, expected in self._counts().items():
            if uint(mfdh.header, offset) != expected or uint(self.container.header, offset, endian='big') != expected:
                raise FormatError(f'library count mismatch at header +0x{offset:x}')
        self._validate_ids_and_refs()

    def _validate_ids_and_refs(self) -> None:
        tracks = self.tracks
        ids = [t.track_id for t in tracks]
        pids = [t.persistent_id for t in tracks]
        if len(ids) != len(set(ids)) or len(pids) != len(set(pids)) or 0 in ids or 0 in pids:
            raise FormatError('zero or duplicate track identity')
        known = set(ids)
        for section, tag, offset in ((9, b'miah', 0xdc), (11, b'miih', 0x1e0)):
            records = self._records(section, tag)
            local_ids = [uint(n.header, 16) for n in records]
            if len(local_ids) != len(set(local_ids)) or 0 in local_ids:
                raise FormatError('zero or duplicate album/artist local ID')
            if any(uint(t.node.header, offset) not in set(local_ids) | {0} for t in tracks):
                raise FormatError('track references a missing album/artist object')
        playlist_pids = []
        for playlist in self.playlists:
            if len(playlist.node.header) >= 0x1c0:
                playlist_pids.append(playlist.persistent_id)
            for track_id in playlist.track_ids:
                if track_id not in known:
                    raise FormatError(f'playlist references missing track {track_id}', playlist.node.offset)
        if len(playlist_pids) != len(set(playlist_pids)) or 0 in playlist_pids:
            raise FormatError('zero or duplicate playlist persistent ID')

    def _require_semantic_profile(self) -> None:
        if self.container.version not in ('12.13.9.1', '12.13.10.3') or len(self.container.header) != 144:
            raise UnsupportedError('writes require the observed Windows iTunes 12.13.9.1/12.13.10.3 profile')
        if self.container.trailer:
            raise UnsupportedError('semantic writes with an unknown compression trailer are unsafe')

    def _sync(self) -> bytes:
        mfdh = self._root(16)
        if not mfdh:
            raise FormatError('cannot serialize a library without mfdh')
        header = bytearray(self.container.header)
        put(mfdh.header, 0x30, len(self.sections))
        put(header, 0x30, len(self.sections), endian='big')
        for offset, value in self._counts().items():
            put(mfdh.header, offset, value)
            put(header, offset, value, endian='big')
        self.container.header = bytes(header)
        payload = serialize_sections(self.sections)
        put(mfdh.header, 8, len(payload) + len(header))
        return serialize_sections(self.sections)

    def to_bytes(self, *, rebuild: bool = False, compression_level: int = 6) -> bytes:
        self._validate_ids_and_refs()
        payload = serialize_sections(self.sections)
        if payload != self.container.payload:
            payload = self._sync()
        self.container.payload = payload
        data = self.container.to_bytes(rebuild=rebuild, compression_level=compression_level)
        # Validate reconstructed framing, derived counts and references, not just zlib.
        Library.from_bytes(data)
        return data

    def write(self, path: str | Path, **kwargs) -> None:
        from .io import write_new
        write_new(Path(path), self.to_bytes(**kwargs))

    def summary(self) -> dict:
        masters = [p for p in self.playlists if p.is_master]
        return {'version': self.container.version, 'file_persistent_id': f'{self.persistent_id:016X}',
                'library_persistent_id': f'{masters[0].persistent_id:016X}' if len(masters) == 1 else None,
                'sections': [{'type': s.section_type, 'offset': s.offset, 'size': len(s.to_bytes()),
                              'opaque': s.children is None} for s in self.sections],
                'tracks': [t.to_dict() for t in self.tracks], 'playlists': [p.to_dict() for p in self.playlists]}

    def to_dict(self) -> dict:
        # Export current state with a correct baseline (still exact for untouched input).
        current = Library.from_bytes(self.to_bytes())
        return {'schema': 'itlkit.library.v1', 'container': current.container.to_dict(),
                'sections': [s.to_dict() for s in current.sections], 'operations': []}

    @classmethod
    def from_dict(cls, value: dict) -> Library:
        if not isinstance(value, dict) or value.get('schema') != 'itlkit.library.v1':
            raise FormatError('unsupported library JSON schema')
        try:
            container = Container.from_dict(value['container'])
            if not container.unchanged:
                raise UnsupportedError('library JSON requires an intact original baseline; raw edits belong to the low-level container API')
            lib = cls(container)
            proposed = serialize_sections([Node.from_dict(s) for s in value['sections']])
            if proposed != container.payload:
                raise UnsupportedError('raw tree edits are not accepted; use the operations array or the low-level container API')
            lib.apply_operations(value.get('operations', []))
            return lib
        except (KeyError, TypeError) as exc:
            raise FormatError(f'invalid library JSON: {exc}') from exc

    def apply_operations(self, operations: list[dict]) -> None:
        if not isinstance(operations, list):
            raise ValueError('operations must be a list')
        # Transactional: no partial mutation if a later operation is rejected.
        candidate = copy.deepcopy(self)
        allowed = {
            'set_track': {'op', 'track_id', 'persistent_id', 'fields'},
            'rename_playlist': {'op', 'persistent_id', 'name'},
            'create_playlist': {'op', 'name', 'persistent_id', 'track_persistent_ids', 'template_persistent_id', 'timestamp_hfs'},
            'delete_playlist': {'op', 'persistent_id'},
            'replace_playlist_members': {'op', 'persistent_id', 'track_persistent_ids'},
            'delete_track': {'op', 'persistent_id'},
        }
        for operation in operations:
            if not isinstance(operation, dict):
                raise ValueError('each operation must be an object')
            action = operation.get('op')
            if not isinstance(action, str) or action not in allowed:
                raise UnsupportedError(f'unsupported operation: {action}')
            if set(operation) - allowed[action]:
                raise ValueError(f'unrecognized {action} key')
            if action == 'set_track':
                if not isinstance(operation.get('fields'), dict):
                    raise ValueError('set_track requires a fields object')
                if set(operation) - {'op', 'track_id', 'persistent_id', 'fields'}:
                    raise ValueError('unrecognized set_track key')
                candidate.track(track_id=operation.get('track_id'), persistent_id=operation.get('persistent_id')).set(**operation['fields'])
            elif action == 'delete_track':
                candidate.delete_track(operation['persistent_id'])
            elif action == 'rename_playlist':
                candidate.playlist(operation['persistent_id']).rename(operation['name'])
            elif action == 'create_playlist':
                candidate.create_playlist(operation['name'], track_persistent_ids=operation.get('track_persistent_ids', []),
                                          persistent_id=operation.get('persistent_id'),
                                          template_persistent_id=operation.get('template_persistent_id'),
                                          timestamp_hfs=operation.get('timestamp_hfs'))
            elif action == 'delete_playlist':
                candidate.delete_playlist(operation['persistent_id'])
            elif action == 'replace_playlist_members':
                candidate.replace_playlist_members(operation['persistent_id'], operation['track_persistent_ids'])
            else:
                raise UnsupportedError(f'unsupported operation: {action}')
        candidate.to_bytes()
        self.container, self.sections = candidate.container, candidate.sections

"""A boundary-driven section/record tree; opaque data is never tag-scanned."""
from __future__ import annotations
from dataclasses import dataclass, field
from .binary import uint, put, prefix
from .errors import FormatError

LIST_ROOTS = {1: b'mlth', 2: b'mlph', 9: b'mlah', 11: b'mlih',
              12: b'mhgh', 13: b'mlth', 14: b'mlph', 15: b'mlrh', 21: b'mlsh'}
CONTAINERS = {b'mith', b'miph', b'miah', b'miih', b'miqh', b'mtph'}
CHILD_COUNT = {b'mith', b'miah', b'miih', b'miqh', b'mtph'}
KINDS = {'total', 'section', 'count', 'fixed', 'mixed'}

@dataclass
class Node:
    header: bytearray
    kind: str = 'total'
    children: list[Node] | None = None
    payload: bytes = b''
    offset: int | None = None

    @property
    def tag(self) -> bytes:
        return bytes(self.header[:4])

    @property
    def section_type(self) -> int | None:
        return uint(self.header, 12) if self.tag == b'msdh' else None

    @property
    def type_code(self) -> int | None:
        return uint(self.header, 12) if self.tag == b'mhoh' else None

    def walk(self):
        yield self
        for child in self.children or ():
            yield from child.walk()

    def to_bytes(self) -> bytes:
        if self.kind not in KINDS or len(self.header) < 12:
            raise FormatError('invalid node model')
        if self.children is not None and self.payload:
            raise FormatError('node cannot have both children and opaque payload')
        body = b''.join(c.to_bytes() for c in self.children) if self.children is not None else bytes(self.payload)
        h = bytearray(self.header)
        put(h, 4, len(h))
        if self.kind in ('total', 'section'):
            put(h, 8, len(h) + len(body))
        if self.children is not None:
            if self.kind == 'count':
                put(h, 8, len(self.children))
            elif self.kind == 'mixed':
                put(h, 12, sum(c.tag == b'mhoh' for c in self.children))
                put(h, 16, sum(c.tag == b'miqh' for c in self.children))
            elif self.tag in CHILD_COUNT:
                put(h, 12, len(self.children))
            elif self.tag == b'miph':
                put(h, 12, sum(c.tag == b'mhoh' for c in self.children))
                put(h, 16, sum(c.tag == b'mtph' for c in self.children))
        return bytes(h) + body

    def to_dict(self) -> dict:
        result = {'tag': self.tag.decode('ascii', errors='replace'), 'kind': self.kind,
                  'header_hex': self.header.hex(), 'offset': self.offset}
        if self.children is None:
            result['payload_hex'] = self.payload.hex()
        else:
            result['children'] = [c.to_dict() for c in self.children]
        return result

    @classmethod
    def from_dict(cls, value: dict, *, depth: int = 0) -> Node:
        if depth > 32:
            raise FormatError('JSON tree exceeds maximum depth')
        try:
            h = bytearray.fromhex(value['header_hex'])
            kind = value['kind']
            if kind not in KINDS:
                raise FormatError('invalid JSON node kind')
            if 'children' in value:
                if value.get('payload_hex'):
                    raise FormatError('ambiguous JSON children and payload')
                children = [cls.from_dict(c, depth=depth + 1) for c in value['children']]
                return cls(h, kind, children)
            return cls(h, kind, None, bytes.fromhex(value['payload_hex']))
        except (KeyError, TypeError, ValueError) as exc:
            if isinstance(exc, FormatError):
                raise
            raise FormatError(f'invalid node JSON: {exc}') from exc


def _check_counts(node: Node) -> None:
    children = node.children or []
    checks = []
    if node.kind == 'count':
        checks.append((8, len(children)))
    elif node.kind == 'mixed':
        checks.extend(((12, sum(c.tag == b'mhoh' for c in children)), (16, sum(c.tag == b'miqh' for c in children))))
    elif node.tag in CHILD_COUNT:
        checks.append((12, len(children)))
    elif node.tag == b'miph':
        checks.extend(((12, sum(c.tag == b'mhoh' for c in children)), (16, sum(c.tag == b'mtph' for c in children))))
    for offset, expected in checks:
        actual = uint(node.header, offset)
        if actual != expected:
            raise FormatError(f'{node.tag!r} child count {actual} != {expected}', (node.offset or 0) + offset)


def _sequence(data: bytes, start: int, end: int, *, fixed_tag: bytes | None = None,
              depth: int = 0) -> list[Node]:
    if depth > 32:
        raise FormatError('record nesting exceeds maximum depth', start)
    result = []
    while start < end:
        tag, hlen, total = prefix(data, start, end)
        if fixed_tag:
            if tag != fixed_tag:
                raise FormatError(f'expected {fixed_tag!r}, got {tag!r}', start)
            total = hlen
        elif not hlen <= total <= end - start:
            raise FormatError(f'invalid {tag!r} total length {total}', start + 8)
        h = bytearray(data[start:start + hlen])
        if tag == b'mhoh' and hlen < 16:
            raise FormatError('mhoh header too short for type code', start)
        node = Node(h, 'fixed' if fixed_tag else 'total', None, data[start + hlen:start + total], start)
        if tag in CONTAINERS and not fixed_tag:
            node.children = _sequence(data, start + hlen, start + total, depth=depth + 1)
            node.payload = b''
            _check_counts(node)
        result.append(node)
        start += total
    return result


def parse_sections(data: bytes) -> list[Node]:
    """Parse msdh boundaries, retaining unknown section bodies as single opaque spans."""
    data = bytes(data)
    sections = []
    start = 0
    while start < len(data):
        tag, hlen, total = prefix(data, start, len(data))
        if tag != b'msdh' or hlen < 16 or not hlen <= total <= len(data) - start:
            raise FormatError('invalid msdh section boundary', start)
        kind = uint(data, start + 12)
        h = bytearray(data[start:start + hlen])
        pos, end = start + hlen, start + total
        sec = Node(h, 'section', None, data[pos:end], start)
        if kind in LIST_ROOTS or kind in (16, 20):
            root_tag, root_hlen, _ = prefix(data, pos, end)
            expected = LIST_ROOTS.get(kind, b'mfdh' if kind == 16 else b'mlqh')
            if root_tag != expected:
                raise FormatError(f'section {kind} expected {expected!r}, got {root_tag!r}', pos)
            root = Node(bytearray(data[pos:pos + root_hlen]), 'fixed', None, b'', pos)
            if kind == 16:
                if pos + root_hlen != end:
                    raise FormatError('unexpected data following mfdh header', pos + root_hlen)
            else:
                root.kind = 'mixed' if kind == 20 else 'count'
                root.children = _sequence(data, pos + root_hlen, end, fixed_tag=b'mprh' if kind == 15 else None)
                _check_counts(root)
            sec.children, sec.payload = [root], b''
        sections.append(sec)
        start = end
    return sections


def serialize_sections(sections: list[Node]) -> bytes:
    return b''.join(section.to_bytes() for section in sections)

"""Guarded structural operations for the observed standalone 12.13.10.3 profile.

Opaque/unknown dependent layouts are rejected, not silently reset. Replacing a
playlist's membership intentionally creates NEW item identities, like native
remove-all/add-in-order; it never changes the underlying track identities.
"""
from __future__ import annotations
import copy
import secrets
from .binary import uint, put
from .errors import FormatError, UnsupportedError
from .model import Node, serialize_sections
from .library import Playlist, set_text, _parse_pid


def require_simple_library(library) -> None:
    library._require_semantic_profile()
    if library.container.version != '12.13.10.3':
        raise UnsupportedError('structural edits require the native-observed 12.13.10.3 profile')
    supported = {16, 12, 9, 11, 1, 13, 23, 2, 14, 21, 4}
    for section in library.sections:
        if section.section_type not in supported:
            raise UnsupportedError(f'structural edits with section {section.section_type} are unverified')
        if section.section_type in (13, 14):
            if section.children and section.children[0].children:
                raise UnsupportedError('nonempty secondary track/playlist lists have unknown dependencies')
        if section.section_type == 23:
            if len(section.payload) != 96 or section.payload[:4] != b'stsh':
                raise UnsupportedError('nonempty store index has unresolved dependencies')
    root = library._root(12)
    if root and any(c.type_code not in (503, 508, 517) for c in root.children or ()):
        raise UnsupportedError('global metadata contains unverified structural references')


def require_plain(playlist: Playlist) -> None:
    if not playlist.is_plain:
        raise UnsupportedError('only ordinary, non-smart, non-system playlists are supported')
    node = playlist.node
    codes = [c.type_code for c in node.children or () if c.tag == b'mhoh']
    if sorted(codes) != [100, 105, 105, 108]:
        raise UnsupportedError('unknown ordinary-playlist metadata layout')
    for child in node.children or ():
        if child.tag not in (b'mhoh', b'mtph'):
            raise UnsupportedError('unknown playlist child record')
        if child.tag == b'mhoh' and child.type_code in (105, 108):
            expected = 1244 if child.type_code == 105 else 220
            if len(child.to_bytes()) != expected:
                raise UnsupportedError('unverified playlist view metadata size')
    # All observed nonzero fields in fresh/native ordinary-playlist headers.
    known = {0, 4, 8, 12, 16, 0x18, 0x1c, 0x1b4, 0x1b8, 0x1bc,
             0x274, 0x730, 0x734, 0xc74, 0xd40}
    for off in range(0, len(node.header) - 3, 4):
        if off not in known and uint(node.header, off):
            raise UnsupportedError(f'ordinary playlist has unknown nonzero state at +0x{off:x}')
    if uint(node.header, 0x18) != 0x10001 or uint(node.header, 0x1b4) != 0x008c0000:
        raise UnsupportedError('unverified ordinary-playlist flags')
    for item in playlist.items:
        if len(item.header) != 84 or item.children or item.payload:
            raise UnsupportedError('unverified playlist item shape')
        item_known = {0, 4, 8, 12, 16, 24, 32, 68, 72}
        if any(uint(item.header, o) for o in range(0, 84, 4) if o not in item_known):
            raise UnsupportedError('playlist item has unknown state that cannot be recreated')


def _all_bytes(library) -> bytes:
    return library.container.header + serialize_sections(library.sections)


class Allocator:
    def __init__(self, library):
        self.raw = _all_bytes(library)
        values = [0]
        for section in library.sections:
            for node in section.walk():
                if node.tag in (b'mith', b'miah', b'miih', b'mtph'):
                    values.append(uint(node.header, 16))
                if node.tag == b'mith':
                    values.append(uint(node.header, 0x1f4))
                elif node.tag == b'mtph':
                    values.append(uint(node.header, 32))
                elif node.tag == b'miph':
                    values.append(uint(node.header, 0xd40))
        self.next_id = max(values) + 1
        self.pids = set()

    def local(self) -> int:
        # Conservative collision guard, NOT a parser or tag-search heuristic:
        # avoid a new identifier appearing anywhere in the existing byte model.
        while self.next_id < 2**32:
            result = self.next_id; self.next_id += 1
            if result.to_bytes(4, 'little') not in self.raw:
                return result
        raise UnsupportedError('no available uint32 local identity')

    def persistent(self, requested: int | str | None = None) -> int:
        if requested is not None:
            requested = _parse_pid(requested)
        for _ in range(100):
            result = secrets.randbits(64) if requested is None else requested
            if type(result) is not int or not 0 < result < 2**64:
                raise ValueError('persistent ID must be a nonzero uint64')
            present = (result in self.pids or result.to_bytes(8, 'little') in self.raw
                       or result.to_bytes(8, 'big') in self.raw
                       or f'{result:016X}'.encode() in self.raw or f'{result:016x}'.encode() in self.raw)
            if not present:
                self.pids.add(result)
                return result
            if requested is not None:
                raise ValueError('requested persistent ID already appears in the library')
        raise UnsupportedError('failed to allocate a unique persistent ID')


def _possible_external_ref(library, excluded: Node, persistent_id: int) -> bool:
    needles = [persistent_id.to_bytes(8, 'little'), persistent_id.to_bytes(8, 'big'),
               f'{persistent_id:016X}'.encode(), f'{persistent_id:016x}'.encode()]
    for section in library.sections:
        if section.section_type == 2:
            root = section.children[0]
            regions = [n.to_bytes() for n in root.children or () if n is not excluded]
        else:
            regions = [section.to_bytes()]
        if any(needle in region for region in regions for needle in needles):
            return True
    return False


def _item(track_id: int, allocator: Allocator) -> Node:
    header = bytearray(84); header[:4] = b'mtph'
    put(header, 4, 84); put(header, 8, 84)
    local_id = allocator.local()
    put(header, 16, local_id); put(header, 24, track_id); put(header, 32, local_id)
    put(header, 68, allocator.persistent(), 8)
    return Node(header, children=[])


def _replace(library, playlist: Playlist, track_persistent_ids, allocator: Allocator) -> None:
    if not isinstance(track_persistent_ids, (list, tuple)):
        raise ValueError('track_persistent_ids must be a list in the desired order')
    tracks = [library.track(persistent_id=pid) for pid in track_persistent_ids]
    for item in playlist.items:
        if _possible_external_ref(library, playlist.node, uint(item.header, 68, 8)):
            raise UnsupportedError('an existing playlist item may be referenced outside its playlist')
    metadata = [n for n in playlist.node.children if n.tag == b'mhoh']
    playlist.node.children = metadata + [_item(t.track_id, allocator) for t in tracks]


def replace_playlist_members(library, persistent_id, track_persistent_ids) -> Playlist:
    candidate = copy.deepcopy(library)
    require_simple_library(candidate)
    playlist = candidate.playlist(persistent_id)
    require_plain(playlist)
    _replace(candidate, playlist, track_persistent_ids, Allocator(candidate))
    candidate.to_bytes()
    library.container, library.sections = candidate.container, candidate.sections
    return library.playlist(persistent_id)


def create_playlist(library, name: str, *, track_persistent_ids=(), persistent_id=None,
                    template_persistent_id=None, timestamp_hfs: int | None = None) -> Playlist:
    candidate = copy.deepcopy(library)
    require_simple_library(candidate)
    if template_persistent_id is not None:
        template = candidate.playlist(template_persistent_id)
        require_plain(template)
    else:
        ordinary = [p for p in candidate.playlists if p.is_plain]
        if ordinary:
            template = ordinary[0]; require_plain(template)
        else:
            masters = [p for p in candidate.playlists if p.is_master]
            if len(masters) != 1:
                raise UnsupportedError('a native playlist view template is required')
            template = masters[0]
    views = [copy.deepcopy(n) for n in template.node.children or () if n.tag == b'mhoh' and n.type_code in (105, 108)]
    if sorted(n.type_code for n in views) != [105, 105, 108]:
        raise UnsupportedError('cannot build a playlist without native view metadata')
    if any(len(n.to_bytes()) != (1244 if n.type_code == 105 else 220) for n in views):
        raise UnsupportedError('unverified view metadata shape')
    allocator = Allocator(candidate)
    pid = allocator.persistent(persistent_id)
    header = bytearray(3500); header[:4] = b'miph'
    put(header, 4, 3500); put(header, 8, 3500); put(header, 0x18, 0x10001)
    put(header, 0x1b4, 0x008c0000); put(header, 0x1b8, pid, 8)
    put(header, 0x734, 0x01000000); put(header, 0xd40, allocator.local())
    when = uint(template.node.header, 0x274) if timestamp_hfs is None else timestamp_hfs
    put(header, 0x1c, when); put(header, 0x274, when)
    node = Node(header, children=[])
    set_text(node, 100, name)
    node.children.extend(views)
    playlist = Playlist(candidate, node)
    root = candidate._root(2)
    if root is None or root.children is None:
        raise UnsupportedError('main playlist list is missing')
    root.children.append(node)
    _replace(candidate, playlist, track_persistent_ids, allocator)
    candidate.to_bytes()
    library.container, library.sections = candidate.container, candidate.sections
    return library.playlist(pid)


def delete_playlist(library, persistent_id) -> None:
    candidate = copy.deepcopy(library)
    require_simple_library(candidate)
    playlist = candidate.playlist(persistent_id)
    require_plain(playlist)
    if _possible_external_ref(candidate, playlist.node, playlist.persistent_id):
        raise UnsupportedError('playlist may be referenced by other opaque metadata or smart rules')
    for item in playlist.items:
        if _possible_external_ref(candidate, playlist.node, uint(item.header, 68, 8)):
            raise UnsupportedError('playlist item may have an external reference')
    root = candidate._root(2)
    root.children.remove(playlist.node)
    candidate.to_bytes()
    library.container, library.sections = candidate.container, candidate.sections

"""Closed-dependency track operations for simple local WAV libraries.

No new media is synthesized. Track import restores a complete native record
from another snapshot of the same library lineage, including its location blob.
Other media/store/cloud/history profiles fail closed.
"""
from __future__ import annotations
import copy
from .binary import uint, put
from .errors import FormatError, UnsupportedError
from .library import Track, read_text, set_text
from .model import Node
from .operations import Allocator, require_simple_library, _all_bytes, _item

AUX = {9: (b'miah', 88, (300, 301, 302)), 11: (b'miih', 100, (400,))}


def _profile(library) -> None:
    require_simple_library(library)
    for playlist in library.playlists:
        if playlist.is_smart and uint(playlist.node.header, 0x238) == 0:
            raise UnsupportedError('custom smart-playlist dependency evaluation is not implemented')


def _wave(track: Track) -> None:
    if len(track.node.header) != 756 or track.get('kind') != 'WAV audio file':
        raise UnsupportedError('track structural/index edits currently require a native local WAV template')
    if uint(track.node.header, 0x14) != 1 or uint(track.node.header, 0x8c) != 1463899680:
        raise UnsupportedError('unverified local WAV record flags')
    known = {1, 2, 3, 4, 5, 6, 8, 11, 12, 13, 27, 30, 31, 32, 33}
    if any(c.tag != b'mhoh' or c.type_code not in known for c in track.node.children or ()):
        raise UnsupportedError('track contains unverified data-object dependencies')
    url = track.get('url')
    if not isinstance(url, str) or not url.lower().startswith('file://'):
        raise UnsupportedError('track has no supported local file URL')


def _aux_profile(node: Node, section: int) -> None:
    tag, size, codes = AUX[section]
    if node.tag != tag or len(node.header) != size:
        raise UnsupportedError('unknown album/artist record profile')
    known = {0, 4, 8, 12, 16, 20, 24, 28}
    if section == 9:
        known.add(40)
    if any(uint(node.header, o) for o in range(0, size, 4) if o not in known):
        raise UnsupportedError('album/artist record has unknown nonzero state')
    if uint(node.header, 28) not in ((2, 0x10002) if section == 9 else (2,)):
        raise UnsupportedError('unverified album/artist flags')
    seen = set()
    for child in node.children or ():
        if child.tag != b'mhoh' or child.type_code not in codes or child.type_code in seen:
            raise UnsupportedError('unverified or ambiguous album/artist metadata')
        read_text(child)
        seen.add(child.type_code)


def _aux(library, section: int, local_id: int) -> Node:
    values = [n for n in library._records(section, AUX[section][0]) if uint(n.header, 16) == local_id]
    if len(values) != 1:
        raise UnsupportedError('track album/artist reference is missing or ambiguous')
    _aux_profile(values[0], section)
    return values[0]


def _text_key(node: Node, section: int) -> tuple:
    values = {c.type_code: read_text(c) for c in node.children or ()}
    return tuple(values.get(code, '') for code in AUX[section][2])


def _external_pid(library, pid: int) -> bool:
    raw = _all_bytes(library)
    return any(n in raw for n in (pid.to_bytes(8, 'little'), pid.to_bytes(8, 'big'),
                                  f'{pid:016X}'.encode(), f'{pid:016x}'.encode()))


def _gc(library, candidates: dict[int, int]) -> list[int]:
    removed = []
    for section, old_id in candidates.items():
        offset = 0xdc if section == 9 else 0x1e0
        if any(uint(t.node.header, offset) == old_id for t in library.tracks):
            continue
        node = _aux(library, section, old_id)
        pid = uint(node.header, 20, 8)
        library._root(section).children.remove(node)
        removed.append(pid)
    return removed


def _check_removed_references(library, pids) -> None:
    if any(_external_pid(library, pid) for pid in set(pids)):
        raise UnsupportedError('removed identities remain in opaque or unsupported dependency records')


def _updated_aux(library, section: int, old: Node, key: tuple, allocator: Allocator) -> int:
    if _text_key(old, section) == key:
        return uint(old.header, 16)
    if any(key):  # Native blank albums/artists are deliberately separate objects.
        for existing in library._records(section, AUX[section][0]):
            _aux_profile(existing, section)
            if _text_key(existing, section) == key:
                return uint(existing.header, 16)
    node = copy.deepcopy(old)
    local_id = allocator.local()
    put(node.header, 16, local_id); put(node.header, 20, allocator.persistent(), 8)
    for code, value in zip(AUX[section][2], key):
        if value:
            set_text(node, code, value)
        else:
            node.children = [c for c in node.children or () if c.type_code != code]
    put(node.header, 28, 2 | (0x10000 if section == 9 and not any(key) else 0))
    library._root(section).children.append(node)
    return local_id


def set_indexed_fields(library, persistent_id, fields) -> Track:
    candidate = copy.deepcopy(library)
    _profile(candidate)
    track = candidate.track(persistent_id=persistent_id)
    _wave(track)
    old_ids = {9: track.get('album_id'), 11: track.get('artist_id')}
    album, artist = _aux(candidate, 9, old_ids[9]), _aux(candidate, 11, old_ids[11])
    indexed = {k: v for k, v in fields.items() if k in ('album', 'artist', 'album_artist')}
    plain = {k: v for k, v in fields.items() if k not in indexed}
    track.set(**plain)
    for name, value in indexed.items():
        if not isinstance(value, str):
            raise ValueError('indexed text must be a string; use an empty string to clear it')
        set_text(track.node, {'album': 3, 'artist': 4, 'album_artist': 27}[name], value)
    album_name = track.get('album') or ''
    album_artist = track.get('album_artist') or ''
    artist_name = track.get('artist') or ''
    if uint(track.node.header, 0x50) & 0x01000000 and not album_artist:
        raise UnsupportedError('compilation grouping without an explicit album artist is unverified')
    effective_artist = album_artist or artist_name
    allocator = Allocator(candidate)
    put(track.node.header, 0xdc, _updated_aux(candidate, 9, album,
        (album_name, effective_artist, album_artist), allocator))
    put(track.node.header, 0x1e0, _updated_aux(candidate, 11, artist, (effective_artist,), allocator))
    removed = _gc(candidate, old_ids)
    _check_removed_references(candidate, removed)
    candidate.to_bytes()
    library.container, library.sections = candidate.container, candidate.sections
    return library.track(persistent_id=persistent_id)


def _import_aux(target, source, section: int, source_id: int, allocator: Allocator) -> int:
    original = _aux(source, section, source_id)
    pid = uint(original.header, 20, 8)
    for existing in target._records(section, AUX[section][0]):
        if uint(existing.header, 20, 8) != pid:
            continue
        _aux_profile(existing, section)
        left, right = copy.deepcopy(existing), copy.deepcopy(original)
        put(left.header, 16, 0); put(right.header, 16, 0)
        if left.to_bytes() != right.to_bytes():
            raise UnsupportedError('same album/artist persistent ID has conflicting content')
        return uint(existing.header, 16)
    allocator.persistent(pid)  # collision/ref guard across all existing bytes
    node = copy.deepcopy(original)
    local_id = allocator.local(); put(node.header, 16, local_id)
    target._root(section).children.append(node)
    return local_id


def _rule_signature(playlist) -> tuple:
    return tuple(c.to_bytes() for c in playlist.node.children or ()
                 if c.tag == b'mhoh' and c.type_code in (101, 102, 103))


def _check_item(node: Node) -> None:
    allowed = {0, 4, 8, 12, 16, 24, 32, 68, 72}
    if len(node.header) != 84 or node.children or node.payload:
        raise UnsupportedError('unknown playlist item dependencies')
    if any(uint(node.header, o) for o in range(0, 84, 4) if o not in allowed):
        raise UnsupportedError('playlist item has unknown nonzero state')


def add_track_from(library, source, persistent_id) -> Track:
    candidate = copy.deepcopy(library)
    _profile(candidate); _profile(source)
    if candidate.persistent_id != source.persistent_id:
        raise UnsupportedError('track restoration currently requires snapshots of the same library lineage')
    original = source.track(persistent_id=persistent_id)
    _wave(original)
    pid = original.persistent_id
    if any(t.persistent_id == pid for t in candidate.tracks):
        raise ValueError('track persistent ID already exists in the destination')
    allocator = Allocator(candidate)
    allocator.persistent(pid)
    album_id = _import_aux(candidate, source, 9, original.get('album_id'), allocator)
    artist_id = _import_aux(candidate, source, 11, original.get('artist_id'), allocator)
    node = copy.deepcopy(original.node)
    new_id = allocator.local(); put(node.header, 16, new_id)
    put(node.header, 0x1f4, allocator.local())
    put(node.header, 0xdc, album_id); put(node.header, 0x1e0, artist_id)
    candidate._root(1).children.append(node)
    donor_playlists = {p.persistent_id: p for p in source.playlists}
    for playlist in candidate.playlists:
        donor = donor_playlists.get(playlist.persistent_id)
        if donor is None:
            if playlist.is_smart or playlist.is_master:
                raise UnsupportedError('destination system/smart playlist has no matching donor definition')
            continue
        if _rule_signature(playlist) != _rule_signature(donor):
            raise UnsupportedError('source and destination playlist rules differ')
        for membership in donor.items:
            if uint(membership.header, 24) == original.track_id:
                _check_item(membership)
                playlist.node.children.append(_item(new_id, allocator))
    if not any(p.is_master and new_id in p.track_ids for p in candidate.playlists):
        raise UnsupportedError('restored track would not belong to the master playlist')
    candidate.to_bytes()
    library.container, library.sections = candidate.container, candidate.sections
    return library.track(persistent_id=pid)


def delete_track(library, persistent_id) -> None:
    candidate = copy.deepcopy(library)
    _profile(candidate)
    track = candidate.track(persistent_id=persistent_id)
    _wave(track)
    old_ids = {9: track.get('album_id'), 11: track.get('artist_id')}
    for section, old in old_ids.items():
        _aux(candidate, section, old)
    removed_pids = [track.persistent_id]
    for playlist in candidate.playlists:
        children = []
        for node in playlist.node.children or ():
            if node.tag == b'mtph' and uint(node.header, 24) == track.track_id:
                _check_item(node)
                removed_pids.append(uint(node.header, 68, 8))
            else:
                children.append(node)
        playlist.node.children = children
    candidate._root(1).children.remove(track.node)
    removed_pids.extend(_gc(candidate, old_ids))
    _check_removed_references(candidate, removed_pids)
    candidate.to_bytes()
    library.container, library.sections = candidate.container, candidate.sections
